// HasActs applies the HasEdge predicate on the "acts" edge.
func HasActs() predicate.OneShotAdventure {
	return predicate.OneShotAdventure(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ActsTable, ActsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasActsWith applies the HasEdge predicate on the "acts" edge with a given conditions (other predicates).
func HasActsWith(preds ...predicate.OneShotAct) predicate.OneShotAdventure {
	return predicate.OneShotAdventure(func(s *sql.Selector) {
		step := newActsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OneShotAdventure) predicate.OneShotAdventure {
	return predicate.OneShotAdventure(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.OneShotAdventure) predicate.OneShotAdventure {
	return predicate.OneShotAdventure(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.OneShotAdventure) predicate.OneShotAdventure {
	return predicate.OneShotAdventure(sql.NotPredicates(p))
}
